SELECT

FROM bt_resource_publish_record a
WHERE a.resource_id = #{resourceId}
AND a.publish_channel = #{publishChannel}
AND a.tenant_id = #{tenantId}
AND a.status_cd = '00A'
 1

SELECT

FROM bt_resource_publish_record a
WHERE a.callback_code = #{callbackCode}
AND a.publish_channel = #{publishChannel}
AND a.status_cd = '00A'
 1

SELECT a.record_id, a.publish_channel, a.publish_status, a.publish_params, a.callback_code,a.created_time,a.last_access_time,
        (SELECT u.real_name FROM bt_user u WHERE u.user_id = a.creator_id) AS "creatorName"
FROM bt_resource_publish_record a
WHERE status_cd = '00A'
  AND tenant_id = #{tenantId}
  AND resource_type = #{resourceType}
  AND resource_id = #{resourceId}

SELECT
,
(SELECT u.real_name FROM bt_user u WHERE u.user_id = a.updator_id) AS "updatorName",
CASE
  WHEN a.resource_type = 'MCP' THEN m.server_name
  WHEN a.resource_type = 'AGENT' THEN s.scene_name
  WHEN a.resource_type = 'TOOL' THEN f.flow_name
  WHEN a.resource_type = 'BOT' THEN g.bot_name
  ELSE NULL
END AS "resourceName"
FROM bt_resource_publish_record a
LEFT JOIN bt_mcp_server m ON a.resource_type = 'MCP' AND m.server_id = a.resource_id AND m.status_cd = '00A' AND m.tenant_id IN (a.tenant_id, -1)
LEFT JOIN bt_bot_scene s ON a.resource_type = 'AGENT' AND s.scene_id = a.resource_id AND s.status_cd = '00A' AND s.tenant_id = a.tenant_id
LEFT JOIN bt_skill_flow f ON a.resource_type = 'TOOL' AND f.flow_id = a.resource_id AND f.status_cd = '00A' AND f.tenant_id IN (a.tenant_id, -1)
LEFT JOIN bt_bot g ON a.resource_type = 'BOT' AND g.bot_id = a.resource_id AND g.status_cd = '00A' AND g.tenant_id IN (a.tenant_id, -1)
WHERE a.status_cd = '00A'

  AND a.tenant_id = #{params.tenantId}


  AND a.resource_type = #{params.resourceType}


  AND a.publish_channel = #{params.publishChannel}


  AND a.publish_status = #{params.publishStatus}


  AND (
    (a.resource_type = 'MCP' AND m.server_name LIKE

      #{params.resourceName}
      )
    OR (a.resource_type = 'AGENT' AND s.scene_name LIKE

      #{params.resourceName}
      )
    OR (a.resource_type = 'TOOL' AND f.flow_name LIKE

      #{params.resourceName}
      )
  )

ORDER BY a.updated_time DESC

SELECT

FROM bt_resource_publish_record a
WHERE a.record_id = #{recordId}

SELECT record_id, callback_code, publish_status
FROM bt_resource_publish_record
WHERE status_cd = '00A'
  AND resource_type = 'AGENT'
  AND tenant_id = #{tenantId}
  AND resource_id = #{botId}
  AND publish_channel = #{publishChannel}
  AND creator_id = #{creatorId}
